using UnityEngine; namespace Mojinloop.Gameplay { public enum HeroState{Idle,Running,Attacking,Dead} public sealed class HeroController:MonoBehaviour { SpriteRenderer spriteRenderer;public HeroState State{get;private set;}=HeroState.Idle;void Awake(){spriteRenderer=GetComponent<SpriteRenderer>();}public void Face(Vector3 target){if(spriteRenderer==null)spriteRenderer=GetComponent<SpriteRenderer>();spriteRenderer.flipX=target.x<transform.position.x;} public void SetState(HeroState state){if(State==HeroState.Dead)return;State=state;} public void Die()=>State=HeroState.Dead; } }
